// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 firstAmount, uint256 secondAmount) public {
        vm.assume(actor != address(0) && actor != address(c));
        firstAmount = bound(firstAmount, 0, 1e30);
        secondAmount = bound(secondAmount, 0, type(uint256).max - firstAmount);

        // seed an initial balance
        vm.deal(actor, firstAmount);
        vm.prank(actor);
        c.addToBalance{value: firstAmount}();
        uint256 before = c.getBalance(actor);

        // top up to a total that stays within uint256
        uint256 top = type(uint256).max - before;
        vm.deal(actor, top);
        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: top}() { ok = true; } catch { ok = false; }

        // General rule: any deposit that keeps the total in range must succeed and
        // record the exact sum; the buggy version reverts (overflow in the unguarded add)
        assertTrue(ok && c.getBalance(actor) == before + top);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, type(uint256).max - 1);

        // fill-up deposit: balance becomes exactly `amount`
        vm.deal(actor, type(uint256).max);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // overflow-inducing deposit: amount + (2^256 - 1 - amount + 1) = 2^256
        vm.deal(actor, type(uint256).max);
        bool wrapped;
        vm.prank(actor);
        try c.addToBalance{value: type(uint256).max - amount + 1}() {
            wrapped = false; // call completed without reverting
        } catch {
            wrapped = true;
        }

        // General rule: after any successful deposits, the recorded balance is
        // the exact total deposited (2^256 here); it never wraps around.
        assertTrue(!wrapped || c.getBalance(actor) == type(uint256).max);
    }
}

