pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(c));
        // wide but biased toward the overflow region so the wrap is findable
        amount = bound(amount, type(uint256).max / 2, type(uint256).max);
        vm.deal(actor, amount);
        uint256 before = c.getBalance(actor);
        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: amount}() { ok = true; } catch { ok = false; }
        // Rule: a successful deposit never decreases the recorded balance.
        assertTrue(!ok || c.getBalance(actor) >= before, "successful deposit must not wrap/decrease balance");
    }
}

